/// Main jq state structure
#[derive(Debug)]
pub struct JqState<T = ()> {
    /// Error callback
    pub err_cb: Option<JqMsgCb<T>>,
    pub err_cb_data: Option<Box<T>>,
    /// Error message callback
    pub error_cb: Option<JqMsgCb<T>>,
    pub error_cb_data: Option<Box<T>>,
    /// Input callback
    pub input_cb: Option<JqInputCb<T>>,
    pub input_cb_data: Option<Box<T>>,
    /// Current input location for input_filename/input_line_number builtins
    pub input_filename: Jv,
    pub input_line: usize,
    /// Debug callback
    pub debug_cb: Option<JqMsgCb<T>>,
    pub debug_cb_data: Option<Box<T>>,
    /// Stderr callback
    pub stderr_cb: Option<JqMsgCb<T>>,
    pub stderr_cb_data: Option<Box<T>>,
    /// No memory handler
    pub nomem_handler: Option<JqNomemHandler<T>>,
    pub nomem_handler_data: Option<Box<T>>,
    /// Execution state
    pub halted: bool,
    pub exit_code: Jv,
    pub error_message: Jv,
    /// Current error for try/catch (separate from error_message)
    pub error: Jv,
    /// Bytecode
    pub bc: Option<Box<Bytecode>>,
    /// Stack
    pub stk: Stack,
    pub curr_frame: StackPtr,
    /// Stack top pointer (for data values)
    pub stk_top: StackPtr,
    /// Fork point top pointer (for backtracking)
    pub fork_top: StackPtr,
    /// Path tracking
    pub path: Jv,
    pub value_at_path: Jv,
    pub subexp_nest: i32,
    /// Debug trace enabled flag
    pub debug_trace_enabled: i32,
    /// Whether this is the initial execution (not backtracking)
    pub initial_execution: bool,
    /// Next label for GENLABEL opcode
    pub next_label: u32,
    /// Attributes
    pub attrs: Jv,
    /// Frames storage (for stack emulation)
    pub frames: Vec<Frame>,
    /// Phantom data for generic type parameter
    pub _phantom: std::marker::PhantomData<T>,
}

impl<T> JqState<T> {
    pub fn new() -> Self {
        Self::default()
    }
}

impl<T> Default for JqState<T> {
    fn default() -> Self {
        JqState {
            err_cb: None,
            err_cb_data: None,
            error_cb: None,
            error_cb_data: None,
            input_cb: None,
            input_cb_data: None,
            input_filename: Jv::invalid(),
            input_line: 0,
            debug_cb: None,
            debug_cb_data: None,
            stderr_cb: None,
            stderr_cb_data: None,
            nomem_handler: None,
            nomem_handler_data: None,
            halted: false,
            exit_code: Jv::invalid(),
            error_message: Jv::invalid(),
            error: Jv::invalid(),
            bc: None,
            stk: Stack {
                mem_end: std::ptr::null_mut(),
                bound: 16,
                limit: 0,
            },
            curr_frame: 0,
            stk_top: 0,
            fork_top: 0,
            path: Jv::invalid(),
            value_at_path: Jv::invalid(),
            subexp_nest: 0,
            debug_trace_enabled: 0,
            initial_execution: true,
            next_label: 0,
            attrs: Jv::invalid(),
            frames: Vec::new(),
            _phantom: std::marker::PhantomData,
        }
    }
}

